/* perf-chat 1.0.0 */
/* Chat no estilo do Claude: classes mc-* usadas pelo patch lib/perf-chat.cjs. */
.mc-user-bubble {
  margin-left: auto;
  max-width: 85%;
  padding: 0.625rem 1rem;
  border-radius: 1.125rem 1.125rem 0.375rem 1.125rem;
  background: color-mix(in oklab, var(--muted) 85%, transparent);
}
.mc-assistant > * + * { margin-top: 0.625rem; }
.mc-msg-footer { opacity: 0.55; transition: opacity 150ms ease; }
.mc-assistant:hover .mc-msg-footer,
.mc-msg-footer:focus-within { opacity: 1; }
.mc-fold-trigger {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  padding: 0.125rem 0;
  border-radius: 0.375rem;
  font-size: var(--text-caption, 0.8125rem);
  color: var(--muted-foreground);
  transition: color 150ms ease;
  cursor: pointer;
}
.mc-fold-trigger:hover { color: var(--foreground); }
.mc-chevron { transition: transform 150ms ease; }
.mc-chevron-open { transform: rotate(90deg); }
.mc-live-dot {
  position: relative;
  display: inline-flex;
  width: 0.5rem;
  height: 0.5rem;
  flex-shrink: 0;
  border-radius: 9999px;
  background: var(--brand);
}
.mc-live-dot::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 9999px;
  background: var(--brand);
  opacity: 0.6;
  animation: mc-ping 1.2s cubic-bezier(0, 0, 0.2, 1) infinite;
}
@keyframes mc-ping { 75%, 100% { transform: scale(2.2); opacity: 0; } }
.mc-fold-body {
  margin-top: 0.375rem;
  margin-left: 5px;
  padding-left: 0.75rem;
  border-left: 1px solid color-mix(in oklab, var(--border) 80%, transparent);
}
.mc-fold-body > * + * { margin-top: 0.25rem; }
.mc-mono { font-family: var(--font-mono); }
.mc-tool-pre {
  margin-top: 0.25rem;
  max-height: 12rem;
  overflow: auto;
  padding: 0.625rem;
  border-radius: 0.375rem;
  border: 1px solid color-mix(in oklab, var(--border) 70%, transparent);
  background: color-mix(in oklab, var(--muted) 35%, transparent);
  font-family: var(--font-mono);
}
.mc-think-pre {
  margin-top: 0.25rem;
  max-height: 12rem;
  overflow: auto;
  padding: 0.25rem 0 0.25rem 0.75rem;
  border-left: 2px solid color-mix(in oklab, var(--border) 80%, transparent);
  font-style: italic;
}
.mc-composer {
  border-radius: 1rem;
  box-shadow: 0 1px 3px 0 #0000001a, 0 1px 2px -1px #0000001a;
  transition: border-color 150ms ease, box-shadow 150ms ease;
}
.mc-composer:focus-within {
  border-color: color-mix(in oklab, var(--foreground) 25%, transparent);
  box-shadow: 0 4px 6px -1px #0000001a, 0 2px 4px -2px #0000001a;
}


/* perf-nav 1.0.0 */
/* Lista de conversas leve: classes usadas pelo patch lib/perf-nav.cjs. */
.mc-thread-row {
  content-visibility: auto;
  contain-intrinsic-size: auto 56px;
}
.mc-load-more {
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: center;
  height: 2.5rem;
  margin-top: 0.25rem;
  border-radius: 0.375rem;
  font-size: var(--text-caption, 0.8125rem);
  color: var(--muted-foreground);
  cursor: pointer;
  transition: background-color 150ms ease, color 150ms ease;
}
.mc-load-more:hover {
  color: var(--foreground);
  background: color-mix(in oklab, var(--accent, var(--muted)) 50%, transparent);
}


/* perf-keepalive 1.0.0 */
/* Animacoes de fundo que forcavam um frame por vsync (patch perf-keepalive). */
[data-visible="false"] > .animate-nav-progress-sweep {
  animation: none !important;
}
.animate-chat-impulse {
  animation-iteration-count: 3 !important;
}


/* automacoes 1.0.0 */
/* Dashboard de Automacoes (patch "automacoes"). Usa os tokens do tema ativo. */
.mc-auto {
  --mc-auto-ok: #22c55e;
  --mc-auto-radius: 16px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  min-height: 0;
  flex: 1 1 0%;
  overflow: auto;
  padding: 16px 20px 24px;
}
.mc-auto-kpis {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  gap: 12px;
}
.mc-auto-kpi,
.mc-auto-card {
  background: var(--surface, var(--background));
  border: 1px solid color-mix(in oklab, var(--border) 80%, transparent);
  border-radius: var(--mc-auto-radius);
  box-shadow: 0 1px 2px #0000000d, 0 8px 24px -12px #0000001f;
}
.mc-auto-kpi {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 16px 18px;
}
.mc-auto-kpi-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  flex-shrink: 0;
  border-radius: 9999px;
}
.mc-tone-green { color: #16a34a; background: #dcfce7; }
.mc-tone-amber { color: #d97706; background: #fef3c7; }
.mc-tone-violet { color: #7c3aed; background: #ede9fe; }
.mc-tone-orange { color: #ea580c; background: #ffedd5; }
.mc-tone-indigo { color: #4f46e5; background: #e0e7ff; }
.dark .mc-tone-green { background: #14532d66; }
.dark .mc-tone-amber { background: #78350f66; }
.dark .mc-tone-violet { background: #4c1d9566; }
.dark .mc-tone-orange { background: #7c2d1266; }
.dark .mc-tone-indigo { background: #312e8166; }
.mc-auto-kpi-label { font-size: 0.8125rem; color: var(--muted-foreground); }
.mc-auto-kpi-value { font-size: 1.75rem; font-weight: 700; line-height: 1.15; color: var(--foreground); font-variant-numeric: tabular-nums; }
.mc-auto-kpi-hint { font-size: 0.75rem; color: var(--muted-foreground); }

.mc-auto-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 300px;
  gap: 16px;
  align-items: start;
}
@media (max-width: 1100px) {
  .mc-auto-grid { grid-template-columns: minmax(0, 1fr); }
}
.mc-auto-card { padding: 18px; min-width: 0; }
.mc-auto-card-head { display: flex; gap: 12px; align-items: flex-start; margin-bottom: 14px; }
.mc-auto-card-head h2 { font-size: 1.125rem; font-weight: 700; color: var(--foreground); }
.mc-auto-card-head p { font-size: 0.8125rem; color: var(--muted-foreground); }
.mc-auto-card-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  flex-shrink: 0;
  border-radius: 10px;
  color: var(--brand);
  background: color-mix(in oklab, var(--brand) 12%, transparent);
}
.mc-auto-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 10px;
}
.mc-auto-tabs {
  display: inline-flex;
  gap: 4px;
  padding: 4px;
  border-radius: 12px;
  background: color-mix(in oklab, var(--muted) 60%, transparent);
}
.mc-auto-tab {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  border-radius: 9px;
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--muted-foreground);
  transition: background-color 150ms ease, color 150ms ease;
}
.mc-auto-tab:hover { color: var(--foreground); }
.mc-auto-tab.is-active {
  color: #fff;
  background: linear-gradient(135deg, var(--brand), color-mix(in oklab, var(--brand) 70%, #a855f7));
