.mc-auto-side-head h3 { font-size: 0.9375rem; font-weight: 700; color: var(--foreground); }
.mc-auto-big { margin-left: auto; font-size: 1.5rem; font-weight: 700; color: var(--foreground); }
.mc-auto-chart { display: block; width: 100%; height: 96px; }
.mc-auto-axis { display: flex; justify-content: space-between; margin-top: 6px; font-size: 0.6875rem; color: var(--muted-foreground); }
.mc-auto-upcoming { display: flex; flex-direction: column; gap: 4px; }
.mc-auto-upcoming li {
  display: flex;
  align-items: center;
