  gap: 10px;
  padding: 8px 10px;
  border-radius: 10px;
  font-size: 0.8125rem;
  color: var(--foreground);
  cursor: pointer;
}
.mc-auto-upcoming li:hover { background: color-mix(in oklab, var(--brand) 6%, transparent); }
.mc-auto-upcoming time {
  flex-shrink: 0;
  padding: 2px 8px;
  border-radius: 9999px;
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--brand);
