}
.mc-auto-health { display: flex; align-items: center; gap: 16px; }
.mc-auto-health ul { display: flex; flex-direction: column; gap: 8px; font-size: 0.8125rem; color: var(--foreground); }
.mc-auto-health li { display: flex; align-items: center; gap: 8px; }
.mc-ok { color: #16a34a; }
.mc-bad { color: #dc2626; }
.mc-muted { color: var(--muted-foreground); }
.mc-auto-ring { position: relative; width: 112px; height: 112px; flex-shrink: 0; }
.mc-auto-ring svg { width: 100%; height: 100%; }
.mc-auto-ring-label { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; }
.mc-auto-ring-label strong { font-size: 1.5rem; font-weight: 700; color: var(--foreground); }
.mc-auto-ring-label span { font-size: 0.6875rem; color: var(--muted-foreground); }


/* chat-agente 1.0.0 */
/* Gaveta "Agente" no chat (patch "chat-agente"). */
.mc-chat-header-row { display: flex; align-items: center; gap: 8px; min-width: 0; }
.mc-chat-header-base { flex: 1 1 0%; min-width: 0; }
.mc-agent-toggle {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 30px;
  padding: 0 10px;
  flex-shrink: 0;
  border-radius: 9px;
  border: 1px solid color-mix(in oklab, var(--border) 80%, transparent);
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--muted-foreground);
  background: var(--background);
  transition: color 150ms ease, border-color 150ms ease, background-color 150ms ease;
}
.mc-agent-toggle:hover { color: var(--foreground); border-color: color-mix(in oklab, var(--foreground) 25%, transparent); }
.mc-agent-toggle.is-open { color: var(--brand); border-color: color-mix(in oklab, var(--brand) 45%, transparent); background: color-mix(in oklab, var(--brand) 8%, transparent); }
.mc-agent-drawer {
  position: fixed;
  top: 56px;
  right: 12px;
  bottom: 12px;
  z-index: 60;
  width: min(380px, calc(100vw - 32px));
  display: flex;
  flex-direction: column;
  border-radius: 16px;
  border: 1px solid color-mix(in oklab, var(--border) 85%, transparent);
  background: var(--background);
  box-shadow: 0 24px 48px -16px #00000040, 0 2px 6px #0000001a;
  animation: mc-drawer-in 160ms ease-out;
}
@keyframes mc-drawer-in { from { opacity: 0; transform: translateX(12px); } to { opacity: 1; transform: none; } }
.mc-agent-drawer-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 14px;
  border-bottom: 1px solid color-mix(in oklab, var(--border) 70%, transparent);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--foreground);
}
.mc-agent-drawer-close {
  width: 28px;
  height: 28px;
  border-radius: 8px;
  color: var(--muted-foreground);
}
.mc-agent-drawer-close:hover { color: var(--foreground); background: color-mix(in oklab, var(--muted) 70%, transparent); }
.mc-agent-drawer-body { flex: 1 1 0%; min-height: 0; overflow-y: auto; }
.mc-agent-drawer-body > * { width: 100% !important; max-width: none !important; border: 0 !important; }
.mc-agent-drawer-empty { padding: 24px; font-size: 0.8125rem; color: var(--muted-foreground); }


/* inicio 1.0.0 */
