  color: #fff;
  background:
    radial-gradient(120% 140% at 0% 0%, color-mix(in oklab, var(--brand) 85%, #a855f7) 0%, transparent 60%),
    linear-gradient(135deg, color-mix(in oklab, var(--brand) 92%, #000) 0%, color-mix(in oklab, var(--brand) 55%, #0ea5e9) 100%);
