.mc-home-sub { margin-top: 6px; font-size: 0.875rem; opacity: 0.9; }
.mc-home-cta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  border-radius: 12px;
  font-size: 0.875rem;
  font-weight: 600;
  white-space: nowrap;
  color: var(--brand);
  background: #fff;
  cursor: pointer;
  transition: transform 120ms ease, box-shadow 120ms ease;
}
.mc-home-cta:hover { transform: translateY(-1px); box-shadow: 0 8px 18px -8px #0000004d; }
.mc-home-shortcuts {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  gap: 12px;
}
.mc-home-shortcut {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 16px;
  border-radius: 14px;
  border: 1px solid color-mix(in oklab, var(--border) 80%, transparent);
  background: var(--surface, var(--background));
  cursor: pointer;
  transition: border-color 140ms ease, transform 140ms ease, box-shadow 140ms ease;
}
.mc-home-shortcut:hover { border-color: color-mix(in oklab, var(--brand) 45%, transparent); transform: translateY(-1px); box-shadow: 0 10px 22px -16px #00000059; }
.mc-home-shortcut strong { display: block; font-size: 0.875rem; font-weight: 600; color: var(--foreground); }
