  box-shadow: 0 1px 2px #0000000d, 0 8px 24px -14px #0000001f;
}
.mc-home-card h2 { margin-bottom: 10px; font-size: 0.9375rem; font-weight: 700; color: var(--foreground); }
.mc-home-empty { padding: 18px 4px; font-size: 0.8125rem; color: var(--muted-foreground); }
.mc-home-list { display: flex; flex-direction: column; gap: 2px; }
