.mc-home-list-side { display: flex; flex-direction: column; align-items: flex-end; gap: 4px; flex-shrink: 0; }
.mc-home-list-side time { font-size: 0.6875rem; color: var(--muted-foreground); font-variant-numeric: tabular-nums; }
.mc-home-avatar-gap { width: 32px; height: 32px; flex-shrink: 0; }
.mc-home-badge {
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  border-radius: 9999px;
  font-size: 0.6875rem;
  font-weight: 700;
  line-height: 18px;
  text-align: center;
  color: #fff;
  background: var(--brand);
}
.mc-home-dot { width: 9px; height: 9px; flex-shrink: 0; border-radius: 9999px; background: #22c55e; box-shadow: 0 0 0 3px #22c55e26; }
.mc-home-dot-offline { background: var(--muted-foreground); box-shadow: none; opacity: 0.6; }
.mc-home-pill {
  flex-shrink: 0;
  padding: 2px 8px;
  border-radius: 9999px;
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--brand);
  background: color-mix(in oklab, var(--brand) 10%, transparent);
