  right: 56px;
  bottom: 16px;
  z-index: 70;
  padding: 7px 12px;
  border-radius: 9px;
  font-size: 0.75rem;
  color: var(--background);
  background: var(--foreground);
  box-shadow: 0 8px 20px -8px #00000060;
  animation: mc-drawer-in 140ms ease-out;
}

/* ------------------------------------------------------------ terminal */
.mc-term-panel {
  position: relative;
  flex-direction: column;
  flex-shrink: 0;
  min-height: 120px;
  border-top: 1px solid color-mix(in oklab, var(--border) 85%, transparent);
  background: var(--background);
  color: var(--foreground);
}
.mc-term-resize { position: absolute; top: -3px; left: 0; right: 0; height: 6px; cursor: row-resize; z-index: 2; }
.mc-term-resize:hover { background: color-mix(in oklab, var(--brand) 35%, transparent); }
.mc-term-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  height: 34px;
  flex-shrink: 0;
  padding: 0 8px;
  border-bottom: 1px solid color-mix(in oklab, var(--border) 60%, transparent);
  font-size: 0.75rem;
}
.mc-term-bar-icon { color: var(--muted-foreground); flex-shrink: 0; }
.mc-term-tabs { display: flex; align-items: center; gap: 2px; flex: 1 1 0%; min-width: 0; overflow-x: auto; scrollbar-width: none; }
.mc-term-tab {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 24px;
  padding: 0 4px 0 8px;
  border-radius: 6px;
  color: var(--muted-foreground);
  cursor: pointer;
  white-space: nowrap;
}
.mc-term-tab:hover { color: var(--foreground); background: color-mix(in oklab, var(--muted) 60%, transparent); }
.mc-term-tab.is-active { color: var(--foreground); background: color-mix(in oklab, var(--muted) 90%, transparent); }
.mc-term-dot { width: 6px; height: 6px; border-radius: 999px; background: #22c55e; }
.mc-term-dot.is-exited { background: var(--muted-foreground); }
.mc-term-tab-close { width: 18px; height: 18px; border-radius: 4px; font-size: 10px; line-height: 1; opacity: 0.55; }
.mc-term-tab-close:hover { opacity: 1; background: color-mix(in oklab, var(--foreground) 12%, transparent); }
.mc-term-btn { display: grid; place-items: center; width: 24px; height: 24px; border-radius: 6px; color: var(--muted-foreground); flex-shrink: 0; }
.mc-term-btn:hover { color: var(--foreground); background: color-mix(in oklab, var(--muted) 70%, transparent); }
.mc-term-shell {
  height: 24px;
  max-width: 150px;
  padding: 0 6px;
  border-radius: 6px;
  border: 1px solid color-mix(in oklab, var(--border) 80%, transparent);
  background: var(--background);
  color: var(--muted-foreground);
  font-size: 0.75rem;
}
.mc-term-body { position: relative; flex: 1 1 0%; min-height: 0; padding: 4px 0 0 10px; }
.mc-term-host { width: 100%; height: 100%; }
.mc-term-host .xterm { height: 100%; }
.mc-term-host .xterm-viewport { background: transparent !important; }
.mc-term-empty { padding: 16px; font-size: 0.8125rem; color: var(--muted-foreground); }

/* ------------------------------------------------------------- sidebar */
.mc-sb {
  position: relative;
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
  min-width: 240px;
  border-left: 1px solid color-mix(in oklab, var(--border) 70%, transparent);
  background: var(--background);
}
.mc-sb-resize { position: absolute; top: 0; bottom: 0; left: -3px; width: 6px; cursor: col-resize; z-index: 2; }
.mc-sb-resize:hover { background: color-mix(in oklab, var(--brand) 35%, transparent); }
.mc-sb-scroll { flex: 1 1 0%; min-height: 0; overflow-y: auto; padding: 8px 0 24px; }
.mc-sb-count {
  margin-left: auto;
  padding: 1px 7px;
  border-radius: 999px;
  font-size: 0.6875rem;
  letter-spacing: 0;
  background: color-mix(in oklab, var(--muted) 85%, transparent);
  color: var(--foreground);
}
.mc-sb-section-body { padding: 2px 4px 4px; font-size: 0.8125rem; }
.mc-sb-row { display: flex; align-items: center; justify-content: space-between; gap: 10px; min-height: 26px; }
.mc-sb-key { display: inline-flex; align-items: center; color: var(--muted-foreground); font-size: 0.75rem; }
.mc-sb-val { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--foreground); text-align: right; }
.mc-sb-chip { padding: 1px 8px; border-radius: 999px; font-size: 0.6875rem; color: var(--muted-foreground); background: color-mix(in oklab, var(--muted) 80%, transparent); }
.mc-sb-chip.is-live { color: var(--brand); background: color-mix(in oklab, var(--brand) 14%, transparent); }
.mc-sb-workdir { margin-top: 8px; display: grid; gap: 6px; }
.mc-sb-path {
  padding: 7px 9px;
  border-radius: 8px;
  font-size: 0.71875rem;
  line-height: 1.35;
  word-break: break-all;
  color: var(--foreground);
  background: color-mix(in oklab, var(--muted) 55%, transparent);
}
.mc-sb-actions, .mc-sb-shortcuts { display: flex; flex-wrap: wrap; gap: 6px; }
.mc-sb-shortcuts { flex-direction: column; align-items: stretch; }
.mc-sb-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 28px;
  padding: 0 10px;
  border-radius: 8px;
  border: 1px solid color-mix(in oklab, var(--border) 80%, transparent);
  font-size: 0.75rem;
  color: var(--foreground);
  background: var(--background);
  transition: border-color 150ms ease, background-color 150ms ease;
}
.mc-sb-btn:hover:not(:disabled) { border-color: color-mix(in oklab, var(--foreground) 25%, transparent); background: color-mix(in oklab, var(--muted) 45%, transparent); }
.mc-sb-btn:disabled { opacity: 0.45; cursor: not-allowed; }
.mc-sb-btn kbd { margin-left: auto; font-size: 0.6875rem; color: var(--muted-foreground); }
.mc-sb-empty { padding: 4px 2px 6px; font-size: 0.75rem; line-height: 1.45; color: var(--muted-foreground); }
.mc-sb-plan, .mc-sb-files, .mc-sb-cmds { display: grid; gap: 2px; list-style: none; margin: 0; padding: 0; }
.mc-sb-plan-item { display: grid; grid-template-columns: 16px 1fr; gap: 8px; align-items: start; padding: 4px 2px; line-height: 1.4; }
.mc-sb-plan-item > svg { margin-top: 2px; color: var(--muted-foreground); }
.mc-sb-plan-item.is-done { color: var(--muted-foreground); }
.mc-sb-plan-item.is-done > span { text-decoration: line-through; text-decoration-color: color-mix(in oklab, var(--muted-foreground) 60%, transparent); }
.mc-sb-plan-item.is-done > svg { color: #22c55e; }
.mc-sb-plan-item.is-running { font-weight: 500; }
.mc-sb-plan-item.is-running > svg { color: var(--brand); }
.mc-sb-file, .mc-sb-cmd { display: flex; align-items: center; gap: 4px; min-width: 0; border-radius: 6px; }
.mc-sb-file:hover, .mc-sb-cmd:hover { background: color-mix(in oklab, var(--muted) 50%, transparent); }
.mc-sb-file-main { display: flex; align-items: center; gap: 6px; flex: 1 1 0%; min-width: 0; height: 26px; padding: 0 4px; text-align: left; }
.mc-sb-file-main > svg { flex-shrink: 0; color: var(--muted-foreground); }
.mc-sb-file-name { flex-shrink: 0; max-width: 60%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--foreground); }
.mc-sb-file-dir { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 0.6875rem; color: var(--muted-foreground); }
.mc-sb-badge { flex-shrink: 0; width: 16px; font-size: 0.6875rem; font-weight: 700; text-align: center; color: #eab308; }
.mc-sb-badge.is-add { color: #22c55e; }
.mc-sb-badge.is-del { color: #ef4444; }
.mc-sb-icon { display: grid; place-items: center; flex-shrink: 0; width: 22px; height: 22px; border-radius: 5px; color: var(--muted-foreground); opacity: 0; transition: opacity 120ms ease; }
.mc-sb-file:hover .mc-sb-icon, .mc-sb-cmd:hover .mc-sb-icon, .mc-sb-icon:focus-visible { opacity: 1; }
.mc-sb-icon:hover { color: var(--foreground); background: color-mix(in oklab, var(--foreground) 10%, transparent); }
.mc-sb-cmd { padding: 2px 2px 2px 6px; }
.mc-sb-cmd code { flex: 1 1 0%; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 0.71875rem; color: var(--foreground); }

/* 1.1: agente, MCPs, plugins e backup */
.mc-sb-field { display: grid; gap: 4px; margin-bottom: 8px; }
.mc-sb-field .mc-sb-key { gap: 6px; }
.mc-sb-field > :not(.mc-sb-key) { width: 100%; min-width: 0; }
.mc-sb-btn-wide { width: 100%; justify-content: center; margin-top: 2px; }
.mc-sb-list { display: grid; gap: 2px; list-style: none; margin: 0; padding: 0; }
.mc-sb-item { display: flex; align-items: center; gap: 8px; min-height: 30px; padding: 0 4px; border-radius: 6px; }
.mc-sb-item:hover { background: color-mix(in oklab, var(--muted) 50%, transparent); }
.mc-sb-item > svg { flex-shrink: 0; color: var(--muted-foreground); }
.mc-sb-item-name { flex: 1 1 0%; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--foreground); }
.mc-sb-item-meta { flex-shrink: 0; font-size: 0.6875rem; color: var(--muted-foreground); }
.mc-sb-switch {
  position: relative;
  flex-shrink: 0;
  width: 28px;
  height: 16px;
  border-radius: 999px;
  background: color-mix(in oklab, var(--muted-foreground) 35%, transparent);
  transition: background-color 150ms ease;
}
.mc-sb-switch > span {
  position: absolute;
  top: 2px;
  left: 2px;
  width: 12px;
  height: 12px;
  border-radius: 999px;
  background: var(--background);
  box-shadow: 0 1px 2px #00000040;
  transition: transform 150ms ease;
}
.mc-sb-switch.is-on { background: var(--brand); }
.mc-sb-switch.is-on > span { transform: translateX(12px); }
.mc-sb-switch:disabled { opacity: 0.45; cursor: not-allowed; }
.mc-sb-switch:focus-visible { outline: 2px solid var(--ring); outline-offset: 1px; }
.mc-sb-backup { display: grid; gap: 6px; }
.mc-sb-backup > .mc-sb-btn { justify-content: center; }
.mc-sb-note { padding: 6px 8px; border-radius: 8px; font-size: 0.75rem; line-height: 1.4; background: color-mix(in oklab, var(--brand) 8%, transparent); color: var(--foreground); }

/* chat-workbench 1.2: layout em cards, terminal em card, filtros */
.mc-wb { background: color-mix(in oklab, var(--muted) 30%, var(--background)); }
.mc-wb-convo { background: var(--background); }
.mc-sb { border-left: 0; background: transparent; padding: 10px 10px 0 6px; }
.mc-sb-scroll { display: grid; align-content: start; gap: 10px; padding: 2px 2px 24px; }
.mc-sb-card {
  border-radius: 14px;
  border: 1px solid color-mix(in oklab, var(--border) 80%, transparent);
  background: var(--background);
  box-shadow: 0 1px 2px #0000000d;
  overflow: hidden;
}
.mc-sb-card-head { display: flex; align-items: center; gap: 4px; padding: 8px 8px 8px 12px; }
.mc-sb-card.is-open .mc-sb-card-head { padding-bottom: 4px; }
.mc-sb-card-toggle { display: flex; align-items: center; gap: 10px; flex: 1 1 0%; min-width: 0; height: 30px; text-align: left; }
.mc-sb-card-icon { display: grid; place-items: center; width: 22px; height: 22px; color: var(--brand); flex-shrink: 0; }
.mc-sb-card-title { flex: 1 1 0%; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 0.875rem; font-weight: 600; color: var(--foreground); }
.mc-sb-card .mc-sb-count { margin-left: 0; }
.mc-sb-chevron, .mc-sb-head-btn { display: grid; place-items: center; flex-shrink: 0; width: 26px; height: 26px; border-radius: 7px; color: var(--muted-foreground); }
.mc-sb-head-btn { color: var(--brand); background: color-mix(in oklab, var(--brand) 10%, transparent); }
.mc-sb-chevron:hover, .mc-sb-head-btn:hover { color: var(--foreground); background: color-mix(in oklab, var(--muted) 80%, transparent); }
.mc-sb-section-body { padding: 2px 14px 12px; }
.mc-sb-count { color: var(--muted-foreground); font-weight: 600; }
.mc-sb-chip { color: var(--brand); background: color-mix(in oklab, var(--brand) 12%, transparent); }
.mc-sb-chip.is-live { color: #16a34a; background: color-mix(in oklab, #16a34a 14%, transparent); }
.mc-sb-path { border: 1px solid color-mix(in oklab, var(--border) 60%, transparent); }
.mc-sb-btn.is-primary { color: #fff; border-color: transparent; background: var(--brand); }
.mc-sb-btn.is-primary:hover:not(:disabled) { background: color-mix(in oklab, var(--brand) 88%, #000); }
.mc-wb-reopen {
  position: absolute;
  top: 50%;
  right: 0;
  z-index: 5;
  display: grid;
  place-items: center;
  width: 22px;
  height: 56px;
  transform: translateY(-50%);
  border-radius: 10px 0 0 10px;
  border: 1px solid color-mix(in oklab, var(--border) 80%, transparent);
  border-right: 0;
  color: var(--brand);
  background: var(--background);
  box-shadow: -2px 0 8px #0000000f;
}
.mc-wb-reopen:hover { width: 28px; }
.mc-wb-flash { right: 20px; }

/* adicionar MCP / plugin */
.mc-sb-add { display: inline-flex; align-items: center; gap: 6px; margin-top: 6px; font-size: 0.75rem; font-weight: 500; color: var(--brand); }
.mc-sb-add:hover { text-decoration: underline; }
.mc-sb-form { display: grid; gap: 6px; margin-top: 8px; padding: 10px; border-radius: 10px; background: color-mix(in oklab, var(--muted) 45%, transparent); }
.mc-sb-input {
  height: 30px;
  padding: 0 9px;
  border-radius: 8px;
  border: 1px solid color-mix(in oklab, var(--border) 90%, transparent);
  background: var(--background);
  font-size: 0.75rem;
  color: var(--foreground);
}
.mc-sb-input:focus { outline: 2px solid color-mix(in oklab, var(--brand) 45%, transparent); outline-offset: 0; }
.mc-sb-error { font-size: 0.6875rem; color: #dc2626; }
.mc-sb-seg { display: flex; gap: 2px; padding: 2px; border-radius: 8px; background: color-mix(in oklab, var(--muted) 80%, transparent); }
.mc-sb-seg > button { flex: 1 1 0%; height: 24px; border-radius: 6px; font-size: 0.6875rem; color: var(--muted-foreground); }
.mc-sb-seg > button.is-on { color: var(--foreground); background: var(--background); box-shadow: 0 1px 2px #0000001a; }
.mc-sb-scopes { margin: 0; padding-left: 16px; font-size: 0.6875rem; color: var(--foreground); }
.mc-sb-item .mc-sb-btn { height: 24px; padding: 0 8px; }
.mc-sb-item:hover .mc-sb-icon { opacity: 1; }

/* explorador de arquivos */
.mc-sb-explorer { display: grid; gap: 6px; }
.mc-sb-crumb { display: flex; align-items: center; gap: 6px; min-width: 0; font-size: 0.6875rem; color: var(--muted-foreground); }
.mc-sb-crumb > span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.mc-sb-icon.is-visible { opacity: 1; }
.mc-sb-icon:disabled { opacity: 0.35; cursor: default; }
.mc-sb-tree { display: grid; max-height: 320px; overflow-y: auto; list-style: none; margin: 0; padding: 0; }
.mc-sb-tree-item { display: flex; align-items: center; gap: 7px; width: 100%; height: 26px; padding: 0 6px; border-radius: 6px; font-size: 0.75rem; text-align: left; color: var(--foreground); }
.mc-sb-tree-item:hover { background: color-mix(in oklab, var(--muted) 55%, transparent); }
.mc-sb-tree-item > svg { flex-shrink: 0; color: var(--muted-foreground); }
.mc-sb-tree-item > span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

/* terminal em card */
.mc-term-panel {
  display: flex;
  margin: 0 12px 12px;
  border-radius: 14px;
  border: 1px solid color-mix(in oklab, var(--border) 85%, transparent);
  box-shadow: 0 1px 3px #0000000f;
}
.mc-term-panel.is-collapsed { min-height: 0; }
.mc-term-panel.is-collapsed .mc-term-bar { border-bottom: 0; }
.mc-term-bar { height: 38px; padding: 0 8px 0 6px; border-radius: 14px 14px 0 0; }
.mc-term-title { padding: 0 6px; font-weight: 500; color: var(--muted-foreground); cursor: pointer; }
.mc-term-btn.is-on { color: var(--brand); background: color-mix(in oklab, var(--brand) 12%, transparent); }
.mc-term-btn-label { width: auto; gap: 2px; padding: 0 5px; display: inline-flex; align-items: center; }
.mc-term-body { padding: 6px 4px 6px 10px; overflow: hidden; border-radius: 0 0 14px 14px; }
.mc-term-body.is-split { display: grid; grid-template-columns: repeat(var(--mc-term-cols, 2), minmax(0, 1fr)); gap: 8px; padding-left: 6px; }
.mc-term-cell { width: 100%; height: 100%; min-width: 0; }
.mc-term-body.is-split .mc-term-cell { padding: 4px 0 0 6px; border-radius: 8px; border: 1px solid color-mix(in oklab, var(--border) 60%, transparent); }
.mc-term-body.is-split .mc-term-cell.is-focused { border-color: color-mix(in oklab, var(--brand) 55%, transparent); }
.mc-term-menu { position: relative; flex-shrink: 0; }
.mc-term-popover {
  position: absolute;
  right: 0;
  bottom: calc(100% + 6px);
  z-index: 80;
  display: grid;
  width: 280px;
  max-height: 320px;
  overflow-y: auto;
  padding: 6px;
  border-radius: 12px;
  border: 1px solid color-mix(in oklab, var(--border) 85%, transparent);
  background: var(--background);
  box-shadow: 0 16px 40px -12px #00000040;
}
.mc-term-popover-title { padding: 6px 8px 2px; font-size: 0.6875rem; font-weight: 600; color: var(--muted-foreground); }
.mc-term-popover > button {
  display: flex;
  align-items: center;
  gap: 6px;
  min-height: 30px;
  padding: 0 8px;
  border-radius: 7px;
  font-size: 0.75rem;
  text-align: left;
  color: var(--foreground);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.mc-term-popover > button:hover:not(:disabled) { background: color-mix(in oklab, var(--muted) 70%, transparent); }
.mc-term-popover > button:disabled { opacity: 0.45; }
.mc-term-popover > button.is-accent { color: var(--brand); font-weight: 500; }

/* filtros da lista de conversas */
.mc-thread-filters { display: flex; flex-wrap: wrap; gap: 6px; padding: 4px 6px 10px; }
.mc-thread-chip {
  height: 26px;
  padding: 0 10px;
  border-radius: 8px;
  border: 1px solid color-mix(in oklab, var(--border) 85%, transparent);
  font-size: 0.75rem;
  color: var(--muted-foreground);
  background: var(--background);
}
.mc-thread-chip:hover { color: var(--foreground); }
.mc-thread-chip.is-on { color: #fff; border-color: transparent; background: var(--brand); }

/* chat-workbench 1.3: memoria local fora da tela, lista compacta e grupos por projeto */
button[aria-label="Memória local das conversas"] { display: none !important; }
.mc-thread-tools { display: inline-flex; gap: 4px; margin-left: auto; }
.mc-thread-tool { display: grid; place-items: center; width: 26px; height: 26px; border-radius: 8px; color: var(--muted-foreground); border: 1px solid transparent; }
.mc-thread-tool:hover { color: var(--foreground); background: color-mix(in oklab, var(--muted) 70%, transparent); }
.mc-thread-tool.is-on { color: var(--brand); border-color: color-mix(in oklab, var(--brand) 35%, transparent); background: color-mix(in oklab, var(--brand) 10%, transparent); }
.mc-thread-group + .mc-thread-group { margin-top: 6px; }
.mc-thread-group-head { display: flex; align-items: center; gap: 6px; width: 100%; height: 28px; padding: 0 6px; border-radius: 7px; font-size: 0.75rem; font-weight: 600; color: var(--muted-foreground); text-align: left; }
.mc-thread-group-head:hover { color: var(--foreground); background: color-mix(in oklab, var(--muted) 55%, transparent); }
.mc-thread-group-head > span:first-of-type { flex: 1 1 0%; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.mc-threads.is-compact .mc-thread-row { height: 34px !important; gap: 8px !important; }
.mc-threads.is-compact .mc-thread-row > :first-child { width: 20px !important; height: 20px !important; }
.mc-threads.is-compact .mc-thread-row [class~="mt-0.5"] { display: none !important; }
.mc-threads.is-compact .mc-thread-row .text-body { font-size: 0.8125rem; }
/* 1.3.1: cards nao encolhem (grid + overflow hidden cortava o conteudo) */
.mc-sb-scroll { display: flex; flex-direction: column; gap: 10px; }
.mc-sb-card { flex-shrink: 0; }

/* 1.4: exibicao do painel (ocultar cards, densidade, altura) e plugins em blocos */
.mc-sb-toolbar { display: flex; align-items: center; gap: 4px; padding: 2px 4px 8px 8px; font-size: 0.75rem; font-weight: 600; color: var(--muted-foreground); }
.mc-sb-toolbar > span { flex: 1 1 0%; }
.mc-sb-head-btn.is-on { color: #fff; background: var(--brand); }
.mc-sb-settings { border-color: color-mix(in oklab, var(--brand) 40%, transparent); }
.mc-sb-gap { margin-top: 10px; margin-bottom: 4px; }
.mc-sb-section-body { scrollbar-width: thin; }
.mc-sb.is-compact .mc-sb-scroll { gap: 6px; }
.mc-sb.is-compact .mc-sb-card { border-radius: 10px; }
.mc-sb.is-compact .mc-sb-card-head { padding: 3px 6px 3px 10px; }
.mc-sb.is-compact .mc-sb-card-toggle { height: 24px; gap: 8px; }
.mc-sb.is-compact .mc-sb-card-title { font-size: 0.8125rem; }
.mc-sb.is-compact .mc-sb-section-body { padding: 0 10px 8px; font-size: 0.75rem; }
.mc-sb.is-compact .mc-sb-row { min-height: 22px; }
.mc-sb.is-comfortable .mc-sb-scroll { gap: 14px; }
.mc-sb.is-comfortable .mc-sb-card-head { padding: 12px 10px 12px 14px; }
.mc-sb.is-comfortable .mc-sb-card-toggle { height: 34px; }
.mc-sb.is-comfortable .mc-sb-card-title { font-size: 0.9375rem; }
.mc-sb.is-comfortable .mc-sb-section-body { padding: 4px 16px 16px; font-size: 0.875rem; }
.mc-sb.is-comfortable .mc-sb-row { min-height: 30px; }
.mc-sb-tiles { display: grid; grid-template-columns: repeat(auto-fill, minmax(118px, 1fr)); gap: 8px; }
.mc-sb-tile { display: grid; gap: 4px; padding: 10px; border-radius: 12px; border: 1px solid color-mix(in oklab, var(--border) 80%, transparent); background: color-mix(in oklab, var(--muted) 25%, var(--background)); min-width: 0; }
.mc-sb-tile.is-on { border-color: color-mix(in oklab, var(--brand) 40%, transparent); background: color-mix(in oklab, var(--brand) 6%, var(--background)); }
.mc-sb-tile-top { display: flex; align-items: center; justify-content: space-between; }
.mc-sb-tile-icon { display: grid; place-items: center; width: 28px; height: 28px; border-radius: 8px; color: var(--brand); background: color-mix(in oklab, var(--brand) 12%, transparent); }
.mc-sb-tile-name { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 0.8125rem; font-weight: 600; color: var(--foreground); }
.mc-sb-tile-meta { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 0.6875rem; color: var(--muted-foreground); }

/* 1.5: pagina de Agentes em blocos */
.mc-view-toggle { display: inline-flex; gap: 2px; padding: 2px; margin-right: 6px; border-radius: 9px; border: 1px solid color-mix(in oklab, var(--border) 85%, transparent); background: color-mix(in oklab, var(--muted) 40%, transparent); }
.mc-view-toggle > button { display: grid; place-items: center; width: 28px; height: 26px; border-radius: 7px; color: var(--muted-foreground); }
.mc-view-toggle > button:hover { color: var(--foreground); }
.mc-view-toggle > button.is-on { color: var(--brand); background: var(--background); box-shadow: 0 1px 2px #0000001a; }
.mc-agent-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 14px; padding: 16px 20px 80px; }
.mc-agent-card { display: flex; flex-direction: column; gap: 10px; min-width: 0; padding: 14px; border-radius: 14px; border: 1px solid color-mix(in oklab, var(--border) 80%, transparent); background: var(--background); box-shadow: 0 1px 2px #0000000d; cursor: pointer; transition: border-color 150ms ease, box-shadow 150ms ease, transform 150ms ease; }
.mc-agent-card:hover { border-color: color-mix(in oklab, var(--brand) 40%, transparent); box-shadow: 0 8px 24px -12px #00000030; transform: translateY(-1px); }
.mc-agent-card.is-selected { border-color: var(--brand); }
.mc-agent-card-top { display: flex; align-items: flex-start; gap: 10px; min-width: 0; }
.mc-agent-card-title { display: grid; gap: 4px; flex: 1 1 0%; min-width: 0; }
.mc-agent-card-name { display: flex; align-items: center; gap: 6px; min-width: 0; font-size: 0.875rem; font-weight: 600; color: var(--foreground); }
.mc-agent-card-name > span:first-child { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.mc-agent-you { flex-shrink: 0; padding: 0 5px; border-radius: 4px; font-size: 0.6875rem; font-weight: 500; color: var(--muted-foreground); background: var(--muted); }
.mc-agent-chip { display: inline-flex; align-items: center; gap: 6px; width: fit-content; max-width: 100%; font-size: 0.75rem; color: var(--muted-foreground); }
.mc-agent-chip.is-warn { color: #d97706; }
.mc-agent-card-actions { flex-shrink: 0; opacity: 0.6; }
.mc-agent-card:hover .mc-agent-card-actions { opacity: 1; }
.mc-agent-card-desc { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; min-height: 2.6em; margin: 0; font-size: 0.75rem; line-height: 1.3; color: var(--muted-foreground); }
.mc-agent-card-meta { display: grid; gap: 4px; }
.mc-agent-meta-item { display: flex; align-items: center; gap: 6px; min-width: 0; font-size: 0.75rem; color: var(--foreground); }
.mc-agent-meta-item > svg { flex-shrink: 0; color: var(--muted-foreground); }
.mc-agent-meta-item > span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.mc-agent-card-foot { display: flex; justify-content: space-between; gap: 8px; padding-top: 8px; border-top: 1px solid color-mix(in oklab, var(--border) 50%, transparent); font-size: 0.6875rem; color: var(--muted-foreground); }
